import { Component, createSignal, Setter } from "solid-js";

import { Button } from "#core/ui-next/components/button.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { BoundBoolean, BoundString } from "#core/ui-next/sandbox/components-browser/components/bound-property.jsx";

export const NavHelpExample: Component = () => {
	const [actionName, setActionName] = createSignal("accept");
	const [disabled, setDisabled] = createSignal(false);

	return (
		<div class="flex flex-row flex-auto mx-4">
			<ScrollArea class="w-1\/3 m-2 p-2 border border-secondary-3">
				<BoundString
					name="actionName"
					signal={[actionName, setActionName as Setter<string | undefined>]}
				/>
				<BoundBoolean
					name="disabled"
					signal={[disabled, setDisabled as Setter<boolean | undefined>]}
				/>
			</ScrollArea>
			<div class="w-2\/3 m-2 p-2 border border-secondary-3 flex flex-col justify-center items-center">
				<Button
					class="border-1"
					name="ExampleActivatable"
					hotkeyAction={actionName()}
				>
					<NavHelp
						class="mr-2"
						actionName={actionName()}
					/>
					From button context
				</Button>
				<div class="mt-8">Alone</div>
				<NavHelp actionName={actionName()} />
			</div>
		</div>
	);
};
